    ns = pylibxc.array_backend.array_namespace(out["vrho"])
    tgt = out["vrho"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.388551349056209e+00, -5.398907423443820e+00, -5.365829048459965e+00, -5.376305304847137e+00, -5.323718074174870e+00, -5.334309111119018e+00, -5.246389054541553e+00, -5.257032046885475e+00, -5.107367033002583e+00, -5.117895342666706e+00, -4.865831317254291e+00, -4.876016132662175e+00, -4.466425039112687e+00, -4.476392177087062e+00, -3.855339313598511e+00, -3.865799900655013e+00, -3.030838597110141e+00, -3.040438218795262e+00, -2.085548474049358e+00, -2.084478882684281e+00, -1.222617263961359e+00, -1.146017257421827e+00, -8.091393272422034e-01, -5.142921828266951e-01, -8.796554918032107e-01, -4.988777189734524e-01, -7.798858046963155e-01, -4.937237063462680e-01, -5.484499699580739e-01, -3.556567033288097e-01, -3.008113140512795e-01, -1.716760974910140e-01, -1.131724850478251e-01, -2.748740319623950e-02, 4.187675655531514e-03, 7.064575294243100e-02, 7.471755194660415e-02, 1.343836599982635e-01, 1.187176732287463e-01, 1.704459414406154e-01]))
